#!/bin/bashCONFIG_FILE="claude.config"EXAMPLE_FILE="claude.config.example"EXTENSIONS_FILE="vscode.extensions"TEMPLATE_ALIASES="claude-dev.aliases"# 1. Check for Config Fileif [ ! -f "$CONFIG_FILE" ]; then    echo "❌ Error: $CONFIG_FILE not found!"    echo "-------------------------------------------------------"    echo "To fix this, please do the following:"    echo " 1. Copy the example: cp $EXAMPLE_FILE $CONFIG_FILE"    echo " 2. Edit $CONFIG_FILE with your server's IP and settings."    echo " 3. Run this script again."    echo "-------------------------------------------------------"    exit 1fisource "$CONFIG_FILE"echo "🚀 Starting Full Automation: Claude Dev + VS Code Setup..."# 2. System Dependencies (Installing gettext for envsubst)sudo apt-get updatesudo apt-get install -y curl git jq gpg apt-transport-https gettext# 3. Install VS Code via APTif ! command -v code &> /dev/null; then    echo "📦 Adding Microsoft VS Code Repository..."    sudo mkdir -p -m 755 /etc/apt/keyrings    # Fixed URLs for Microsoft Repo    curl -fsSL https://microsoft.com | gpg --dearmor | sudo tee /etc/apt/keyrings/microsoft.gpg > /dev/null    echo "deb [arch=amd64,arm64,armhf signed-by=/etc/apt/keyrings/microsoft.gpg] https://microsoft.com stable main" | sudo tee /etc/apt/sources.list.d/vscode.list > /dev/null    echo "📦 Installing VS Code..."    sudo apt-get update    sudo apt-get install -y codeelse    echo "✅ VS Code is already installed."fi# 4. Install VS Code Extensions from fileif [ -f "$EXTENSIONS_FILE" ]; then    echo "🧩 Installing VS Code extensions..."    while IFS= read -r extension || [ -n "$extension" ]; do        [[ -z "$extension" || "$extension" =~ ^# ]] && continue        code --install-extension "$extension" --force    done < "$EXTENSIONS_FILE"fi# 5. Install Claude Code CLIecho "📦 Installing Claude Code CLI..."# Added -s to curl and used full install pathcurl -fsSL https://claude.ai | bash# 6. Configure Claude CLI JSONmkdir -p "$HOME/.claude"cat <<EOF > "$HOME/.claude/config.json"{  "autoConnectToEditor": true,  "defaultModel": "${LOCAL_MODEL_NAME}",  "primaryModel": "${LOCAL_MODEL_NAME}"}EOF# 7. Setup Aliases from TemplateALIAS_DEST="$HOME/.claude_aliases"if [ -f "$TEMPLATE_ALIASES" ]; then    echo "✍️  Generating $ALIAS_DEST from template..."    # We export the variables so envsubst can see them    export REMOTE_SERVER_IP REMOTE_SERVER_PORT LOCAL_API_KEY OFFICIAL_API_KEY LOCAL_MODEL_NAME    envsubst < "$TEMPLATE_ALIASES" > "$ALIAS_DEST"else    echo "❌ Error: Template $TEMPLATE_ALIASES not found!"fi# 8. Source in .bashrcBASHRC="$HOME/.bashrc"if ! grep -qF "source $ALIAS_DEST" "$BASHRC"; then    echo -e "\n# Custom Claude Aliases\nsource $ALIAS_DEST" >> "$BASHRC"fiecho "------------------------------------------------"echo "✅ Setup Complete!"echo "------------------------------------------------"echo "1. Run 'source ~/.bashrc'"echo "2. Open your project: 'code .'"echo "3. Start coding: 'claude-local'"echo "------------------------------------------------"